def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            opp_c += 1

    c_to_c = 0
    c_to_d = 0
    d_to_c = 0
    d_to_d = 0

    for i in range(1, n):
        prev_my = history[i - 1][0]
        curr_opp = history[i][1]
        if prev_my == 'C':
            if curr_opp == 'C':
                c_to_c += 1
            else:
                c_to_d += 1
        else:
            if curr_opp == 'C':
                d_to_c += 1
            else:
                d_to_d += 1

    c_samples = c_to_c + c_to_d
    d_samples = d_to_c + d_to_d

    p_d_after_c = c_to_d / float(c_samples) if c_samples else 0.0
    p_d_after_d = d_to_d / float(d_samples) if d_samples else 0.0

    punisher = (
        d_samples >= 2 and
        p_d_after_d >= 0.6 and
        (p_d_after_d - p_d_after_c) >= 0.25
    )

    unresponsive = d_samples >= 3 and (
        p_d_after_d <= 0.45 or
        p_d_after_d <= p_d_after_c + 0.25
    )

    opp_rate = opp_c / float(n)
    my_d = n - my_c

    recent10 = history[-10:] if n >= 10 else history
    recent5 = history[-5:] if n >= 5 else history

    recent10_d = sum(1 for _, b in recent10 if b == 'D')
    recent5_d = sum(1 for _, b in recent5 if b == 'D')

    if n >= 2:
        prev_my2, prev_opp2 = history[-2]
    else:
        prev_my2, prev_opp2 = my_last, opp_last

    if opp_c == 0:
        return 'D'

    if recent10_d >= 8 and opp_rate <= 0.35:
        return 'D'

    if my_last == 'D' and opp_last == 'C':
        if prev_opp2 == 'D':
            return 'C'
        if opp_c == n:
            return 'D'
        if punisher:
            return 'C'
        if opp_rate >= 0.85 and recent5_d == 0:
            return 'D'
        if unresponsive and recent10_d <= 4 and opp_rate >= 0.7:
            return 'D'
        return 'C'

    if my_last == 'D' and opp_last == 'D':
        if unresponsive and recent10_d >= 2 and opp_rate < 0.75:
            return 'D'
        if punisher and opp_rate >= 0.3:
            return 'C'
        if opp_rate >= 0.55 or recent5_d <= 1:
            return 'C'
        return 'D'

    if my_last == 'C' and opp_last == 'D':
        if prev_my2 == 'D':
            return 'C'
        return 'D'

    if opp_c == n:
        if my_d == 0:
            if n >= 20:
                return 'D'
        else:
            return 'D'

    if unresponsive and (c_samples + d_samples) >= 12 and recent10_d <= 6:
        return 'D'

    if punisher:
        return 'C'

    if opp_rate >= 0.9 and recent10_d == 0:
        if my_d > 0 and n >= 70:
            return 'D'
        if n >= 90:
            return 'D'

    return 'C'
